use vstd::prelude::*;

verus! {

fn bmat(
    top_left: Vec<f32>,
    top_right: Vec<f32>,
    bottom_left: Vec<f32>,
    bottom_right: Vec<f32>,
) -> (result: Vec<f32>)
    requires
        top_right.len() == top_left.len(),
        bottom_left.len() == top_left.len(),
        bottom_right.len() == top_left.len(),
        // capacity computation should not overflow usize
        top_left.len() <= usize::MAX / 4,
    ensures
        result.len() == top_left.len() * 4,
        // result is a concatenation of the four input vectors
        result@ == top_left@ + top_right@ + bottom_left@ + bottom_right@,
{
    let n = top_left.len();
    assert_eq!(top_right.len(), n, "top_right must have the same length as top_left");
    assert_eq!(bottom_left.len(), n, "bottom_left must have the same length as top_left");
    assert_eq!(bottom_right.len(), n, "bottom_right must have the same length as top_left");

    let mut result = Vec::with_capacity(n * 4);
    result.extend_from_slice(&top_left);
    result.extend_from_slice(&top_right);
    result.extend_from_slice(&bottom_left);
    result.extend_from_slice(&bottom_right);
    result
}

} // verus!

